cat > src/parsers.cpp <<'EOF'
#include "parsers.hpp"
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <climits>
#include <map>
#include <vector>
#include <cctype>

namespace loop {
static uint32_t next_char(const std::string &s, size_t &i) {
    unsigned char c=s[i++];
    if(c<128) return c;
    int remain= c>=0xf0 ? 3 : c>=0xe0 ? 2 : 1;
    uint32_t n=c & (0x7f >> (remain+1));
    while(remain-- && i<s.size()) n=(n<<6)|(static_cast<unsigned char>(s[i++])&0x3f);
    return n;
}
bool valid_utf8(const std::string &s) {
    for(size_t i=0;i<s.size();) {
        unsigned char c=s[i++];
        if(c<0x80) continue;
        int remain;
        uint32_t n, minimum;
        if(c>=0xc2 && c<=0xdf) {remain=1;n=c&31;minimum=0x80;}
        else if(c>=0xe0 && c<=0xef) {remain=2;n=c&15;minimum=0x800;}
        else if(c>=0xf0 && c<=0xf4) {remain=3;n=c&7;minimum=0x10000;}
        else return false;
        while(remain--) {
            if(i==s.size() || (static_cast<unsigned char>(s[i])&0xc0)!=0x80) return false;
            n=(n<<6)|(static_cast<unsigned char>(s[i++])&63);
        }
        if(n<minimum || n>0x10ffff || (n>=0xd800 && n<=0xdfff)) return false;
    }
    return true;
}
static bool space(uint32_t c) {
    return (c>=9 && c<=13) || c==32 || c==0x85 || c==0xa0 || c==0x1680 || (c>=0x2000 && c<=0x200a) || c==0x2028 || c==0x2029 || c==0x202f || c==0x205f || c==0x3000;
}
static void skip_space(const std::string &s,size_t &i) {
    while(i<s.size()) {
        size_t j=i;
        if(!space(next_char(s,j))) break;
        i=j;
    }
}
static bool digit(char c) {return c>='0' && c<='9';}
static bool letter(char c) {return (c>='a' && c<='z') || (c>='A' && c<='Z');}

double parse_float(const std::string &s) {
    if(s.empty()) throw ParseError("cannot parse float from empty string");
    std::string lower=s;
    for(char &c:lower) if(c>='A' && c<='Z') c+=32;
    if(lower[0]=='+' || lower[0]=='-') lower.erase(0,1);
    if(lower=="nan") return std::numeric_limits<double>::quiet_NaN();
    if(lower=="inf" || lower=="infinity") return s[0]=='-' ? -INFINITY : INFINITY;
    size_t i=0;
    if(s[i]=='+' || s[i]=='-') ++i;
    bool found=false;
    while(i<s.size() && digit(s[i])) {++i;found=true;}
    if(i<s.size() && s[i]=='.') {
        ++i;
        while(i<s.size() && digit(s[i])) {++i;found=true;}
    }
    if(!found) throw ParseError("invalid float literal");
    if(i<s.size() && (s[i]=='e' || s[i]=='E')) {
        ++i;
        if(i<s.size() && (s[i]=='+' || s[i]=='-')) ++i;
        size_t begin=i;
        while(i<s.size() && digit(s[i])) ++i;
        if(i==begin) throw ParseError("invalid float literal");
    }
    if(i!=s.size()) throw ParseError("invalid float literal");
    return std::strtod(s.c_str(),nullptr);
}
size_t counter_precision(const std::string &s) {
    auto dot=s.find('.');
    if(dot==std::string::npos) return 0;
    size_t end=dot+1;
    while(end<s.size() && digit(s[end])) ++end;
    return end-dot-1;
}

Duration parse_duration(const std::string &s) {
    // Units are deliberately case-sensitive; 'M' means a month, 'm' a minute.
    static const std::map<std::string,std::pair<uint64_t,uint32_t>> units={
        {"ns",{0,1}},{"nsec",{0,1}},{"nanos",{0,1}},
        {"us",{0,1000}},{"usec",{0,1000}},
        {"ms",{0,1000000}},{"msec",{0,1000000}},
        {"s",{1,0}},{"sec",{1,0}},{"secs",{1,0}},{"second",{1,0}},{"seconds",{1,0}},
        {"m",{60,0}},{"min",{60,0}},{"mins",{60,0}},{"minute",{60,0}},{"minutes",{60,0}},
        {"h",{3600,0}},{"hr",{3600,0}},{"hrs",{3600,0}},{"hour",{3600,0}},{"hours",{3600,0}},
        {"d",{86400,0}},{"day",{86400,0}},{"days",{86400,0}},
        {"w",{604800,0}},{"week",{604800,0}},{"weeks",{604800,0}},
        {"M",{2630016,0}},{"month",{2630016,0}},{"months",{2630016,0}},
        {"y",{31557600,0}},{"year",{31557600,0}},{"years",{31557600,0}}
    };
    size_t i=0;
