namespace loop {
const std::vector<OptionSpec>& option_specs() {
    static const std::vector<OptionSpec> specs = {
        {"count-by", 'b', "count_by", "Amount to increment the counter by", "1"},
        {"error-duration", 'D', "", "Exit with timeout error code on duration", {}},
