        {"for", 0, "ffor", "A comma-separated list of values, placed into 4ITEM. ex., red,green,blue", {}},
        {"for-duration", 'd', "for_duration", "Keep going until the duration has elapsed (example 1m30s)", {}},
        {"help", 'h', "", "Prints help information", {}},
        {"num", 'n', "num", "Number of iterations to execute", {}},
        {"offset", 'o', "offset", "Amount to offset the initial counter by", "0"},
        {"only-last", 'l', "", "Only print the output of the last execution of the command", {}},
        {"stdin", 'i', "", "Read from standard input", {}},
        {"summary", 0, "", "Provide a summary", {}},
        {"until-changes", 'C', "", "Keep going until the output changes", {}},
        {"until-contains", 'c', "until_contains", "Keep going until the output contains this string", {}},
        {"until-error", 'r', "until_error", "Keep going until the command exit status is the value given", {}},
        {"until-fail", 'f', "", "Keep going until the command exit status is non-zero", {}},
        {"until-match", 'm', "until_match", "Keep going until the output matches this regular expression", {}},
        {"until-same", 'S', "", "Keep going until the output changes", {}},
        {"until-success", 's', "", "Keep going until the command exit status is zero", {}},
        {"until-time", 't', "until_time", "Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)", {}},
        {"version", 'V', "", "Prints version information", {}}
    };
    return specs;
}

static const OptionSpec* find_long(const std::string &name) {
    for (const auto &s : option_specs()) if (s.name == name) return &s;
    return nullptr;
}
static const OptionSpec* find_short(char ch) {
    for (const auto &s : option_specs()) if (s.short_name && s.short_name == ch) return &s;
    return nullptr;
}

void print_help(const std::string &program) {
    std::cout << "loop 0.6.1\nRich Jones <miserlou@gmail.com>\nUNIX's missing `loop` command\n\nUSAGE:\n    "
              << program << " [FLAGS] [OPTIONS] [input]...\n\nFLAGS:\n";
    for (bool values : {false, true}) {
        if (values) std::cout << "\nOPTIONS:\n";
        size_t width = values ? 39 : 23;
        for (const auto &s : option_specs()) {
            if (s.takes_value() != values) continue;
            std::string left = s.short_name ? std::string("    -") + s.short_name + ", " : "        ";
            left += s.usage();
            std::cout << left << std::string(width + 4 > left.size() ? width + 4 - left.size() : 1, ' ')
                      << s.description;
            if (s.default_value) std::cout << " [default: " << *s.default_value << "]";
            std::cout << '\n';
        }
    }
    std::cout << "\nARGS:\n    <input>...    The command to be looped\n";
}

static std::string usage(const Options &o, bool defaults, const std::string &extra = "") {
    std::string res = o.program;
    bool any = false;
    for (const auto &s : option_specs()) {
        if (o.occurrences.count(s.name) || (defaults && s.default_value) || s.name == extra) {
            res += " " + s.usage(); any = true;
        }
    }
    if (!any) res += " [FLAGS] [OPTIONS] [input]...";
    return res;
}

static void cli_error(const std::string &message, const Options &o, bool defaults, const std::string &extra = "") {
    std::cerr << "error: " << message << "\n\nUSAGE:\n    " << usage(o, defaults, extra)
              << "\n\nFor more information try --help\n";
    throw Exit(1);
}

// Match misspelled long options with the same conservative similarity rule used
// by the observed interface. Short options never have spelling suggestions.
static double similarity(const std::string &a, const std::string &b) {
    if (a == b) return 1.0;
    if (a.empty() || b.empty()) return 0.0;
    int radius = std::max(0, int(std::max(a.size(),b.size()) / 2) - 1);
    std::vector<bool> ma(a.size()), mb(b.size());
    unsigned match=0, trans=0;
    for (int i=0; i<(int)a.size(); ++i) {
        for (int j=std::max(0,i-radius); j<std::min(int(b.size()),i+radius+1); ++j) {
            if (!mb[j] && a[i]==b[j]) { ma[i]=true; mb[j]=true; ++match; break; }
        }
    }
    if (!match) return 0.0;
    size_t j=0;
    for (size_t i=0;i<a.size();++i) if(ma[i]) {
        while (!mb[j]) ++j;
        if(a[i]!=b[j]) ++trans;
        ++j;
    }
    double m=match;
    double score=(m/a.size()+m/b.size()+(m-double(trans)/2)/m)/3;
    if (score>0.7) {
        size_t p=0;
        while (p<std::min({size_t(4),a.size(),b.size()}) && a[p]==b[p]) ++p;
        score += p * 0.1 * (1-score);
    }
    return score;
}

static void unknown(const std::string &argument, const Options &o, const std::string &name = "") {
    std::string suggestion;
    double best=0.8;
    if (!name.empty()) {
        for (const auto &s : option_specs()) {
            double score=similarity(name, s.name);
            if(score>best) { best=score; suggestion=s.name; }
        }
    }
    std::string msg="Found argument '" + argument + "' which wasn't expected, or isn't valid in this context";
    if (!suggestion.empty()) msg += "\n\tDid you mean \033[32m--\033[0m\033[32m" + suggestion + "\033[0m?";
    cli_error(msg,o,false,suggestion);
}

void invalid_value(const std::string &name, const std::string &reason) {
    auto spec=find_long(name);
    std::cerr << "error: Invalid value for '" << (spec ? spec->usage() : name) << "': " << reason << '\n';
    throw Exit(1);
}

Options parse_options(int argc, char **argv) {
    Options o;
    o.program=argc ? argv[0] : "executable";
    auto slash=o.program.find_last_of('/');
    if(slash!=std::string::npos) o.program.erase(0,slash+1);
    bool positional=false;
    const OptionSpec *pending=nullptr;
    auto add=[&](const OptionSpec &s, const std::optional<std::string> &v) {
        if(s.name=="help") { print_help(o.program); throw Exit(0); }
        if(s.name=="version") { std::cout << "loop 0.6.1\n"; throw Exit(0); }
        ++o.occurrences[s.name];
        auto &dest=o.values[s.name];
        if(v) dest.push_back(*v);
    };
    for(int i=1;i<argc;++i) {
        std::string arg=argv[i];
        if(positional) { o.command.push_back(arg); continue; }
        if(arg=="--") { positional=true; pending=nullptr; continue; }
        if(arg.size()>1 && arg[0]=='-') {
            pending=nullptr;
            if(arg[1]=='-') {
                auto eq=arg.find('=');
                std::string name=arg.substr(2,eq==std::string::npos ? std::string::npos : eq-2);
                auto spec=find_long(name);
                if(!spec) unknown("--"+name,o,name);
                std::optional<std::string> value;
                if(spec->takes_value() && eq!=std::string::npos) value=arg.substr(eq+1);
                add(*spec,value);
                if(spec->takes_value() && !value) pending=spec;
            } else {
                for(size_t j=1;j<arg.size();++j) {
                    auto spec=find_short(arg[j]);
                    if(!spec) unknown(std::string("-")+arg[j],o);
                    std::optional<std::string> value;
                    if(spec->takes_value() && j+1<arg.size()) {
                        size_t start=j+1;
                        if(arg[start]=='=') ++start;
                        value=arg.substr(start);
                    }
                    add(*spec,value);
                    if(spec->takes_value()) {
                        if(!value) pending=spec;
                        break;
                    }
                }
            }
        } else if(pending) {
            o.values[pending->name].push_back(arg); pending=nullptr;
        } else {
            o.command.push_back(arg);
        }
    }
    for(const auto &s : option_specs()) {
        if(s.default_value && (!o.values.count(s.name) || o.values[s.name].empty()))
            o.values[s.name].push_back(*s.default_value);
    }
    return o;
}

void check_occurrences(const Options &o) {
    for(const auto &s : option_specs()) {
        auto it=o.occurrences.find(s.name);
        if(it==o.occurrences.end()) continue;
        if(s.takes_value() && o.values.at(s.name).empty())
            cli_error("The argument '"+s.usage()+"' requires a value but none was supplied",o,true);
        if(it->second>1)
            cli_error("The argument '"+s.usage()+"' was provided more than once, but cannot be used multiple times",o,true);
    }
}
}
