        if(c>=0xc2 && c<=0xdf) {remain=1;n=c&31;minimum=0x80;}
        else if(c>=0xe0 && c<=0xef) {remain=2;n=c&15;minimum=0x800;}
        else if(c>=0xf0 && c<=0xf4) {remain=3;n=c&7;minimum=0x10000;}
