size_t chars(const std::string &s,size_t a,size_t b) {
    size_t n=0;
    for(size_t i=a;i<b && i<s.size();++i) if((static_cast<unsigned char>(s[i])&0xc0)!=0x80) ++n;
    return n;
}
std::string diagnostic(const std::string &p,size_t start,size_t len,const std::string &message) {
    std::string r="regex parse error:\n";
    if(p.find('\n')==std::string::npos) {
        r+="    "+p+"\n    "+std::string(chars(p,0,start)+(start>p.size() ? start-p.size():0),' ')
            +std::string(std::max(size_t(1),chars(p,start,start+len)),'^')+"\n";
    } else {
        r+=std::string(79,'~')+"\n";
        size_t lines=1+std::count(p.begin(),p.end(),'\n');
        size_t width=std::to_string(lines).size(), pos=0, line=1;
        while(pos<=p.size()) {
            size_t end=p.find('\n',pos);
            if(end==std::string::npos) end=p.size();
            auto label=std::to_string(line);
            r+=std::string(width-label.size(),' ')+label+": "+p.substr(pos,end-pos)+"\n";
            if(start>=pos && start<=end) r+=std::string(width+2+chars(p,pos,start),' ')
                +std::string(std::max(size_t(1),chars(p,start,std::min(end,start+len))),'^')+"\n";
            if(end==p.size()) break;
            pos=end+1; ++line;
        }
        r+=std::string(79,'~')+"\n";
    }
    return r+"error: "+message;
}
using Ranges=std::vector<std::pair<uint32_t,uint32_t>>;
Ranges normalize(Ranges s) {
    std::sort(s.begin(),s.end());
    Ranges r;
    for(auto v:s) {
        if(v.first>v.second) continue;
        if(!r.empty() && v.first<=r.back().second+1) r.back().second=std::max(v.second,r.back().second);
        else r.push_back(v);
    }
    return r;
}
Ranges union_set(Ranges a,const Ranges &b) { a.insert(a.end(),b.begin(),b.end()); return normalize(a); }
Ranges intersect(const Ranges &a,const Ranges &b) {
    Ranges r;
    for(auto x:a) for(auto y:b) if(std::max(x.first,y.first)<=std::min(x.second,y.second))
        r.push_back({std::max(x.first,y.first),std::min(x.second,y.second)});
    return normalize(r);
}
Ranges complement(const Ranges &a) {
    Ranges r;
    uint32_t i=0;
    for(auto v:a) { if(i<v.first) r.push_back({i,v.first-1}); i=v.second+1; }
    if(i<=0x10ffff) r.push_back({i,0x10ffff});
    return intersect(r,{{0,0xd7ff},{0xe000,0x10ffff}});
}
std::string hexchar(uint32_t c) {
    std::ostringstream ss;
    ss << "\\x{" << std::hex << c << "}";
    return ss.str();
}
std::string set_pattern(const Ranges &rs) {
    if(rs.empty()) return "(?!)";
    std::string r="[";
    for(auto v:rs) {r+=hexchar(v.first); if(v.second!=v.first) r+="-"+hexchar(v.second);}
    return r+"]";
}
struct CharExpr {
    std::string text;
    std::optional<Ranges> known;
    std::optional<uint32_t> literal;
    size_t start=0, end=0;
};
CharExpr literal_expr(uint32_t c,size_t start,size_t end) { return {hexchar(c),Ranges{{c,c}},c,start,end}; }
CharExpr combine(CharExpr a,CharExpr b,const std::string &op) {
    std::optional<Ranges> s;
    if(a.known && b.known) {
        if(op=="|") s=union_set(*a.known,*b.known);
        else if(op=="&&") s=intersect(*a.known,*b.known);
        else if(op=="--") s=intersect(*a.known,complement(*b.known));
        else s=union_set(intersect(*a.known,complement(*b.known)),intersect(*b.known,complement(*a.known)));
    }
    std::string t;
    if(s) t=set_pattern(*s);
    else if(op=="|") t="(?:"+a.text+"|"+b.text+")";
    else if(op=="&&") t="(?="+a.text+")"+b.text;
    else if(op=="--") t="(?!"+b.text+")"+a.text;
    else t="(?:(?!"+b.text+")"+a.text+"|(?!"+a.text+")"+b.text+")";
    return {t,s,{},a.start,b.end};
}

class Translator {
