        else if(name=="alpha") set={{'A','Z'},{'a','z'}};
        else if(name=="alnum") set={{'0','9'},{'A','Z'},{'a','z'}};
        else if(name=="word") set={{'0','9'},{'A','Z'},{'_','_'},{'a','z'}};
        else if(name=="lower") set={{'a','z'}};
        else if(name=="upper") set={{'A','Z'}};
        else if(name=="ascii") set={{0,127}};
        else if(name=="space") set={{9,13},{32,32}};
        else if(name=="blank") set={{9,9},{32,32}};
        else if(name=="cntrl") set={{0,31},{127,127}};
        else if(name=="graph") set={{33,126}};
        else if(name=="print") set={{32,126}};
        else if(name=="punct") set={{33,47},{58,64},{91,96},{123,126}};
