    std::string expression(Flags f,bool nested=false) {
        std::string out;
        while(true) {
            ws(f);
            if(i==p.size()) break;
            if(p[i]==')') {
                if(!nested) fail(i,1,"unopened group");
                break;
            }
            if(p[i]=='|') {out+='|';++i;continue;}
            if(std::string("*+?{").find(p[i])!=std::string::npos) fail(i,1,"repetition operator missing expression");
