}
struct Pattern::Impl {
    pcre2_code *code=nullptr;
    pcre2_match_data *data=nullptr;
    ~Impl() {if(data) pcre2_match_data_free(data); if(code) pcre2_code_free(code);}
};
Pattern::Pattern(const std::string &text) : impl(std::make_unique<Impl>()) {
    Translator t(text);
    std::string pattern=t.translate();
    int error;
    PCRE2_SIZE offset;
    impl->code=pcre2_compile((PCRE2_SPTR)pattern.c_str(),pattern.size(),PCRE2_UTF|PCRE2_UCP,&error,&offset,nullptr);
    if(!impl->code) {
        if(error==PCRE2_ERROR_PATTERN_TOO_LARGE || error==PCRE2_ERROR_QUANTIFIER_TOO_BIG)
            throw ParseError("Compiled regex exceeds size limit of 10485760 bytes.");
        throw ParseError(diagnostic(text,std::min<size_t>(offset,text.size()),1,"invalid regular expression"));
    }
    impl->data=pcre2_match_data_create_from_pattern(impl->code,nullptr);
}
Pattern::~Pattern()=default;
bool Pattern::matches(const std::string &text) const {
    return pcre2_match(impl->code,(PCRE2_SPTR)text.c_str(),text.size(),0,0,impl->data,nullptr)>=0;
}
}
