using Clock=std::chrono::steady_clock;

[[noreturn]] static void panic(const std::string &location,const std::string &message) {
    std::cerr << "\nthread 'main' (" << getpid() << ") panicked at " << location << ":\n" << message
              << "\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n";
    throw Exit(101);
}
static void print(const std::string &s) {
    const char *p=s.data();
    size_t remaining=s.size();
    while(remaining) {
        ssize_t n=write(STDOUT_FILENO,p,remaining);
        if(n<0) {
            if(errno==EINTR) continue;
            panic("library/std/src/io/stdio.rs:1165:9", "failed printing to stdout: "+std::string(std::strerror(errno))+" (os error "+std::to_string(errno)+")");
        }
        if(!n) break;
        p+=n;remaining-=n;
    }
}
static std::vector<std::string> lines(const std::string &s) {
    std::vector<std::string> result;
    size_t pos=0;
    while(pos<s.size()) {
        auto end=s.find('\n',pos);
        if(end==std::string::npos) {result.push_back(s.substr(pos));break;}
        auto len=end-pos;
        if(len && s[end-1]=='\r') --len;
        result.push_back(s.substr(pos,len));
        pos=end+1;
    }
    return result;
}
static void print_output(const std::string &s) {for(auto &line:lines(s)) print(line+"\n");}
static std::string read_input() {
    std::string result;
    char b[16384];
    while(true) {
        ssize_t n=read(STDIN_FILENO,b,sizeof(b));
        if(n<0) {
            if(errno==EINTR) continue;
            panic("src/main.rs:48:29", "called `Result::unwrap()` on an `Err` value: Os { code: "+std::to_string(errno)+", kind: Other, message: \""+std::strerror(errno)+"\" }");
        }
        if(n==0) break;
        result.append(b,n);
    }
    if(!valid_utf8(result)) panic("src/main.rs:48:29", "called `Result::unwrap()` on an `Err` value: Error { kind: InvalidData, message: \"stream did not contain valid UTF-8\" }");
    return result;
}
struct Result {std::string output;unsigned code;};
static Result execute(const std::string &command) {
    int output[2], failure[2];
    if(pipe2(output,O_CLOEXEC)<0 || pipe2(failure,O_CLOEXEC)<0)
        panic("src/main.rs:118:24","called `Result::unwrap()` on an `Err` value: IoError(Os { code: "+std::to_string(errno)+", kind: Other, message: \""+std::strerror(errno)+"\" })");
    pid_t pid=fork();
    if(pid<0) panic("src/main.rs:118:24","called `Result::unwrap()` on an `Err` value: IoError(Os { code: "+std::to_string(errno)+", kind: Other, message: \""+std::strerror(errno)+"\" })");
    if(pid==0) {
        close(output[0]);close(failure[0]);
        dup2(output[1],STDOUT_FILENO);dup2(output[1],STDERR_FILENO);close(output[1]);
        signal(SIGPIPE,SIG_DFL);
        char sh[]="sh", opt[]="-c";
        char *argv[]={sh,opt,const_cast<char*>(command.c_str()),nullptr};
        execvp(sh,argv);
        int e=errno;
        (void)!write(failure[1],&e,sizeof(e));
        _exit(127);
    }
    close(output[1]);close(failure[1]);
    int e=0;
    ssize_t n;
    do {n=read(failure[0],&e,sizeof(e));} while(n<0 && errno==EINTR);
    close(failure[0]);
    if(n>0) {
        close(output[0]);waitpid(pid,nullptr,0);
        std::string kind=e==ENOENT ? "NotFound" : e==EACCES ? "PermissionDenied" : "Other";
        panic("src/main.rs:118:24","called `Result::unwrap()` on an `Err` value: IoError(Os { code: "+std::to_string(e)+", kind: "+kind+", message: \""+std::strerror(e)+"\" })");
    }
    std::string data;
    char b[16384];
    while(true) {
        n=read(output[0],b,sizeof(b));
        if(n<0 && errno==EINTR) continue;
        if(n<=0) break;
        data.append(b,n);
    }
    close(output[0]);
    int status=0;
    while(waitpid(pid,&status,0)<0) if(errno!=EINTR) {status=-1;break;}
    if(!valid_utf8(data)) panic("src/main.rs:123:45", "read failed: Error { kind: InvalidData, message: \"stream did not contain valid UTF-8\" }");
    return {data,WIFEXITED(status) ? (unsigned)WEXITSTATUS(status) : 99u};
}
static std::string format_count(double count,size_t precision) {
    if(std::isnan(count)) return "NaN";
    if(std::isinf(count)) return std::signbit(count) ? "-inf" : "inf";
    int n=snprintf(nullptr,0,"%.*f",static_cast<int>(precision),count);
    if(n<0) return "0";
    std::vector<char> b(static_cast<size_t>(n)+1);
    snprintf(b.data(),b.size(),"%.*f",static_cast<int>(precision),count);
    return std::string(b.data(),n);
}
static std::optional<unsigned> error_number(const std::string &s) {
    size_t pos=0;
    if(s.empty()) return {};
    if(s[0]=='+') ++pos;
    if(pos==s.size()) return {};
    uint64_t n=0;
    while(pos<s.size()) {
        if(s[pos]<'0' || s[pos]>'9') return {};
        n=n*10+(s[pos++]-'0');
        if(n>UINT32_MAX) return {};
    }
    return (unsigned)n;
}
static uint64_t as_integer(double x) {
    if(!(x>0)) return 0;
    if(x>=static_cast<double>(UINT64_MAX)) return UINT64_MAX;
    return static_cast<uint64_t>(x);
}

int run(int argc,char **argv) {
    auto start=Clock::now();
    signal(SIGPIPE,SIG_IGN);
    Options opt=parse_options(argc,argv);
    // Validate supplied values before acting on the command or reading stdin.
    for(const auto &s:option_specs()) {
        auto it=opt.values.find(s.name);
        if(it==opt.values.end()) continue;
        for(const auto &v:it->second) {
            try {
                if(s.name=="num" || s.name=="offset" || s.name=="count-by") (void)parse_float(v);
                if(s.name=="every" || s.name=="for-duration") (void)parse_duration(v);
                if(s.name=="until-time") (void)parse_timestamp(v);
                if(s.name=="until-match") {Pattern validate(v);}
            } catch(const ParseError &e) {invalid_value(s.name,e.what());}
        }
    }
    check_occurrences(opt);
    double step=parse_float(opt.get("count-by"));
    double counter=parse_float(opt.get("offset"))-step;
    size_t precision=counter_precision(opt.get("count-by"));
    auto every=parse_duration(opt.get("every"));
    std::optional<Duration> duration;
    if(opt.has("for-duration")) duration=parse_duration(opt.get("for-duration"));
    std::optional<long double> until;
    if(opt.has("until-time")) until=parse_timestamp(opt.get("until-time"));
    std::unique_ptr<Pattern> pattern;
    if(opt.has("until-match")) pattern=std::make_unique<Pattern>(opt.get("until-match"));
    std::optional<unsigned> target;
    if(opt.has("until-error")) target=error_number(opt.get("until-error"));
    std::vector<std::string> items;
    if(opt.has("for")) {
        const auto &s=opt.get("for");
        size_t pos=0;
        while(true) {
            auto end=s.find(',',pos);
            if(end==std::string::npos) {items.push_back(s.substr(pos));break;}
            items.push_back(s.substr(pos,end-pos));pos=end+1;
        }
    }
    if(opt.has("stdin") || !isatty(STDIN_FILENO)) {
        auto input=lines(read_input());
        items.insert(items.end(),input.begin(),input.end());
    }
    std::string command;
    for(size_t i=0;i<opt.command.size();++i) {
        if(i) command+=' ';
        command+=opt.command[i];
    }
    if(command.empty()) {print("No command supplied, exiting.\n");return 0;}
    uint64_t count=opt.has("num") ? as_integer(parse_float(opt.get("num"))) : items.empty() ? UINT64_MAX : items.size();
    uint64_t runs=0,successes=0;
    std::vector<unsigned> failures;
    std::string first,last;
    int exitcode=0;
    for(uint64_t index=0;index<count;++index) {
        auto iteration_start=Clock::now();
        if(duration && std::chrono::duration<long double>(iteration_start-start).count()>=duration->as_seconds()) {
            if(opt.has("error-duration")) exitcode=124;
            break;
        }
        if(until && std::chrono::duration<long double>(std::chrono::system_clock::now().time_since_epoch()).count()>=*until) break;
        counter+=step;
        std::string number=format_count(counter,precision);
        setenv("COUNT",number.c_str(),1);
        if(index<items.size()) {
            if(items[index].find('\0')!=std::string::npos)
                panic("library/std/src/env.rs:364:9","failed to set environment variable `\"ITEM\"`: `\""+items[index]+"\"`");
            setenv("ITEM",items[index].c_str(),1);
        }
        auto result=execute(command);
        ++runs;
        if(result.code==0) ++successes;
        else failures.push_back(result.code);
        last=std::move(result.output);
        if(index==0) first=last;
        bool stop=false;
        if(!opt.has("only-last")) print_output(last);
        for(const auto &line:lines(last)) {
            if(opt.has("until-contains") && line.find(opt.get("until-contains"))!=std::string::npos) stop=true;
            if(pattern && pattern->matches(line)) stop=true;
        }
        if(opt.has("until-fail") && result.code!=0) stop=true;
        if(opt.has("until-success") && result.code==0) stop=true;
        if(opt.has("until-error") && (target ? result.code==*target : result.code!=0)) stop=true;
        if(index>0 && opt.has("until-changes") && last!=first) stop=true;
        if(index>0 && opt.has("until-same") && last==first) stop=true;
        if(stop) break;
        auto elapsed=std::chrono::duration<long double>(Clock::now()-iteration_start).count();
        auto remaining=every.as_seconds()-elapsed;
        if(remaining>0) std::this_thread::sleep_for(std::chrono::duration<long double>(remaining));
    }
    if(opt.has("only-last")) print_output(last);
    if(opt.has("summary")) {
        std::string summary="Total runs:\t"+std::to_string(runs)+"\nSuccesses:\t"+std::to_string(successes)+"\nFailures:\t"+std::to_string(failures.size());
        if(!failures.empty()) {
            summary+=" (";
            for(size_t i=0;i<failures.size();++i) {
                if(i) summary+=", ";
                summary+=std::to_string(failures[i]);
            }
            summary+=")";
        }
        print(summary+"\n");
    }
    return exitcode;
}
}
int main(int argc,char **argv) {
    try {return loop::run(argc,argv);}
    catch(const loop::Exit &e) {return e.status;}
    catch(const std::exception &e) {std::cerr << e.what() << '\n';return 101;}
}
