    std::string r="regex parse error:\n";
    if(p.find('\n')==std::string::npos) {
        r+="    "+p+"\n    "+std::string(chars(p,0,start)+(start>p.size() ? start-p.size():0),' ')
            +std::string(std::max(size_t(1),chars(p,start,start+len)),'^')+"\n";
