        size_t width=std::to_string(lines).size(), pos=0, line=1;
        while(pos<=p.size()) {
            size_t end=p.find('\n',pos);
            if(end==std::string::npos) end=p.size();
            auto label=std::to_string(line);
            r+=std::string(width-label.size(),' ')+label+": "+p.substr(pos,end-pos)+"\n";
            if(start>=pos && start<=end) r+=std::string(width+2+chars(p,pos,start),' ')
                +std::string(std::max(size_t(1),chars(p,start,std::min(end,start+len))),'^')+"\n";
            if(end==p.size()) break;
