Ranges union_set(Ranges a,const Ranges &b) { a.insert(a.end(),b.begin(),b.end()); return normalize(a); }
Ranges intersect(const Ranges &a,const Ranges &b) {
    Ranges r;
    for(auto x:a) for(auto y:b) if(std::max(x.first,y.first)<=std::min(x.second,y.second))
        r.push_back({std::max(x.first,y.first),std::min(x.second,y.second)});
    return normalize(r);
