CharExpr literal_expr(uint32_t c,size_t start,size_t end) { return {hexchar(c),Ranges{{c,c}},c,start,end}; }
CharExpr combine(CharExpr a,CharExpr b,const std::string &op) {
    std::optional<Ranges> s;
    if(a.known && b.known) {
        if(op=="|") s=union_set(*a.known,*b.known);
        else if(op=="&&") s=intersect(*a.known,*b.known);
        else if(op=="--") s=intersect(*a.known,complement(*b.known));
        else s=union_set(intersect(*a.known,complement(*b.known)),intersect(*b.known,complement(*a.known)));
